package api

import "testing"

func makeAgent(t *testing.T, base string) float64 {
	t.Helper()
	r := doRequest(t, base, "POST", "/api/agents", map[string]any{"name": "Ada", "email": "ada@example.com"})
	return r.body["id"].(float64)
}

func TestCreateTicketValidatesAgent(t *testing.T) {
	srv := startServer(t)
	defer srv.Close()

	bad := doRequest(t, srv.URL, "POST", "/api/tickets", map[string]any{"subject": "Help", "agentId": 999})
	if bad.status != 400 {
		t.Fatalf("expected 400, got %d", bad.status)
	}

	agentID := makeAgent(t, srv.URL)
	created := doRequest(t, srv.URL, "POST", "/api/tickets", map[string]any{"subject": "Help", "agentId": agentID})
	if created.status != 201 {
		t.Fatalf("expected 201, got %d", created.status)
	}
	if created.body["status"] != "open" {
		t.Fatalf("expected default status open, got %v", created.body["status"])
	}
}

func TestListTicketsPaginationComposesWithFilters(t *testing.T) {
	srv := startServer(t)
	defer srv.Close()

	a1 := makeAgent(t, srv.URL)
	a2 := makeAgent(t, srv.URL)

	for i := 0; i < 5; i++ {
		doRequest(t, srv.URL, "POST", "/api/tickets", map[string]any{"subject": "a", "agentId": a1})
	}
	for i := 0; i < 5; i++ {
		doRequest(t, srv.URL, "POST", "/api/tickets", map[string]any{"subject": "b", "agentId": a2})
	}

	page1 := doRequest(t, srv.URL, "GET", "/api/tickets?agentId="+jsonNum(a1)+"&page=1&pageSize=2", nil)
	if page1.body["total"].(float64) != 5 {
		t.Fatalf("expected total 5 (filtered count), got %v", page1.body["total"])
	}
	tickets1, _ := page1.body["tickets"].([]any)
	if len(tickets1) != 2 {
		t.Fatalf("expected 2 tickets on page 1, got %d", len(tickets1))
	}
	for _, raw := range tickets1 {
		ticket := raw.(map[string]any)
		if int(ticket["agentId"].(float64)) != int(a1) {
			t.Fatalf("page 1 leaked a ticket from a2: %v", ticket)
		}
	}

	page3 := doRequest(t, srv.URL, "GET", "/api/tickets?agentId="+jsonNum(a1)+"&page=3&pageSize=2", nil)
	tickets3, _ := page3.body["tickets"].([]any)
	if len(tickets3) != 1 {
		t.Fatalf("expected 1 ticket on page 3 (5 filtered / pageSize 2), got %d", len(tickets3))
	}

	badPage := doRequest(t, srv.URL, "GET", "/api/tickets?page=0", nil)
	if badPage.status != 400 {
		t.Fatalf("expected 400 for page=0, got %d", badPage.status)
	}
}

func TestUpdateTicketValidatesStatusAndPriority(t *testing.T) {
	srv := startServer(t)
	defer srv.Close()

	created := doRequest(t, srv.URL, "POST", "/api/tickets", map[string]any{"subject": "A"})
	id := jsonNum(created.body["id"])

	badStatus := doRequest(t, srv.URL, "PATCH", "/api/tickets/"+id, map[string]any{"status": "bogus"})
	if badStatus.status != 400 {
		t.Fatalf("expected 400 for bad status, got %d", badStatus.status)
	}

	ok := doRequest(t, srv.URL, "PATCH", "/api/tickets/"+id, map[string]any{"priority": "high"})
	if ok.status != 200 || ok.body["priority"] != "high" {
		t.Fatalf("unexpected update result: status=%d body=%v", ok.status, ok.body)
	}
}

